"use client";
import { useEffect, useRef, useState } from "react";
import { INDUSTRIES, type Scenario, type TradeKey } from "@/lib/site-content";

// The sample call player: pick a trade and a scenario, read the transcript and the texts that go
// out, and play the call (ElevenLabs voices, generated by /api/samples).

const TRADES: { id: TradeKey; label: string }[] = [
  { id: "contractors", label: "Contractor call" },
  { id: "mechanics", label: "Mechanic shop call" },
  { id: "retail", label: "Storefront call" },
];

export function DispatchSimulator({ initialTrade = "contractors" }: { initialTrade?: TradeKey }) {
  const [trade, setTrade] = useState<TradeKey>(initialTrade);
  const [scenario, setScenario] = useState<Scenario>("customer");
  const [status, setStatus] = useState<"idle" | "loading" | "playing" | "paused" | "error">("idle");
  const audio = useRef<HTMLAudioElement>(null);
  const call = INDUSTRIES[trade].simulation[scenario];

  // A different call: stop the current one.
  useEffect(() => {
    audio.current?.pause();
    setStatus("idle");
  }, [trade, scenario]);

  const toggle = async () => {
    const el = audio.current;
    if (!el) return;
    if (status === "playing") {
      el.pause();
      return;
    }
    const src = `/api/samples/${trade}/${scenario}`;
    if (!el.src.endsWith(src)) {
      el.src = src;
      setStatus("loading");
    }
    try {
      await el.play();
    } catch {
      setStatus("error");
    }
  };

  const tab = (selected: boolean) => (selected ? { backgroundColor: "#D8B47A", color: "#1F3B2D" } : { backgroundColor: "#173022", color: "#EFE6D4" });
  const scenarioBtn = (selected: boolean) => (selected ? { backgroundColor: "#EFE6D4", color: "#1F3B2D", borderColor: "#EFE6D4" } : { backgroundColor: "#173022", color: "#EFE6D4", borderColor: "#EFE6D4" });

  return (
    <section id="dispatch-simulator" className="scroll-mt-24 border-t-4 border-[#173022] bg-[#1F3B2D] py-16 text-[#EFE6D4]">
      <div className="mx-auto max-w-7xl px-4 sm:px-6 lg:px-8">
        <div className="mb-10 flex flex-col justify-between gap-6 lg:flex-row lg:items-end">
          <div>
            <div style={{ letterSpacing: "0.2em" }} className="font-condensed-700 mb-2 text-sm uppercase text-[#D8B47A]">Hear a sample call &amp; the texts that go out</div>
            <h2 style={{ lineHeight: 0.95 }} className="font-condensed-800 text-4xl text-[#EFE6D4] sm:text-[48px]">See how the dispatcher handles customers vs. suppliers.</h2>
          </div>
          <div className="flex flex-wrap gap-2" role="group" aria-label="Trade">
            {TRADES.map((t) => (
              <button key={t.id} type="button" aria-pressed={trade === t.id} onClick={() => setTrade(t.id)} style={tab(trade === t.id)} className="cursor-pointer rounded-[6px] px-4 py-2 text-xs font-semibold uppercase tracking-wider">
                {t.label}
              </button>
            ))}
          </div>
        </div>

        <div className="mb-6 flex flex-wrap gap-3" role="group" aria-label="Scenario">
          <button type="button" aria-pressed={scenario === "customer"} onClick={() => setScenario("customer")} style={scenarioBtn(scenario === "customer")} className="h-[48px] cursor-pointer rounded-[12px] border-2 px-5 text-sm font-semibold">Scenario A: Customer booking a job</button>
          <button type="button" aria-pressed={scenario === "supplier"} onClick={() => setScenario("supplier")} style={scenarioBtn(scenario === "supplier")} className="h-[48px] cursor-pointer rounded-[12px] border-2 px-5 text-sm font-semibold">Scenario B: Parts supplier / vendor call</button>
        </div>

        <div className="grid items-start gap-6 lg:grid-cols-12">
          <div className="space-y-4 rounded-[20px] border-2 border-[#6B5A43] bg-[#173022] p-6 lg:col-span-7">
            <div className="flex flex-wrap items-center justify-between gap-3 border-b border-[#1F3B2D] pb-4">
              <div className="flex flex-wrap items-center gap-3">
                <button type="button" onClick={toggle} className="inline-flex h-[44px] cursor-pointer items-center gap-2 rounded-[12px] bg-[#D8B47A] px-4 text-sm font-semibold text-[#1F3B2D]" aria-label={status === "playing" ? "Pause the sample call" : "Play the sample call"}>
                  {status === "playing" ? (
                    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" aria-hidden="true"><path d="M9 5v14M15 5v14" /></svg>
                  ) : (
                    <svg width="18" height="18" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M8 5.5v13a1 1 0 0 0 1.5.86l10-6.5a1 1 0 0 0 0-1.72l-10-6.5A1 1 0 0 0 8 5.5z" /></svg>
                  )}
                  {status === "playing" ? "Pause" : status === "loading" ? "Loading…" : status === "paused" ? "Resume" : "Play the call"}
                </button>
                <span className="text-sm font-semibold text-[#EFE6D4]">{call.caller}</span>
              </div>
              <span className="font-condensed-700 text-xs uppercase tracking-widest text-[#D8B47A]">{call.badge}</span>
            </div>
            {status === "error" ? <p className="text-sm text-[#D8B47A]">The recording isn&apos;t ready yet. Try again in a minute; the transcript is below.</p> : null}
            <audio
              ref={audio}
              preload="none"
              onPlaying={() => setStatus("playing")}
              onPause={() => setStatus((s) => (s === "playing" ? "paused" : s))}
              onEnded={() => setStatus("idle")}
              onError={() => setStatus("error")}
            />
            <ol className="space-y-3">
              {call.transcript.map((line, i) => {
                const ai = line.speaker === "AI Dispatcher";
                return (
                  <li key={i} style={{ backgroundColor: ai ? "#1F3B2D" : "#EFE6D4", color: ai ? "#EFE6D4" : "#1F3B2D" }} className="rounded-[12px] p-4">
                    <div style={{ color: ai ? "#D8B47A" : "#6B5A43" }} className="mb-1 text-xs font-bold uppercase tracking-wider">{line.speaker}</div>
                    <p className="text-sm font-medium leading-relaxed sm:text-base">&ldquo;{line.text}&rdquo;</p>
                  </li>
                );
              })}
            </ol>
          </div>

          <div className="space-y-4 lg:col-span-5">
            <div className="space-y-3 rounded-[20px] border-2 border-[#D8B47A] bg-[#EFE6D4] p-6 text-[#1F3B2D]">
              <div className="flex items-center justify-between">
                <span style={{ letterSpacing: "0.15em" }} className="font-condensed-700 text-xs uppercase text-[#A87A33]">Instant SMS to your cell</span>
                <span className="text-xs font-semibold text-[#6B5A43]">Sent as the call ends</span>
              </div>
              <div className="rounded-[12px] bg-[#1F3B2D] p-4 font-mono text-xs leading-relaxed text-[#EFE6D4] sm:text-sm">{call.smsToOwner}</div>
            </div>
            <div className="space-y-3 rounded-[20px] border-2 border-[#6B5A43] bg-[#EFE6D4] p-6 text-[#1F3B2D]">
              <span style={{ letterSpacing: "0.15em" }} className="font-condensed-700 text-xs uppercase text-[#6B5A43]">{call.clientLabel}</span>
              <div className="rounded-[12px] border border-[#1F3B2D] p-4 text-xs font-medium leading-relaxed sm:text-sm">{call.smsToClient}</div>
            </div>
            <p className="text-xs text-[#EFE6D4]/80">Sample call with example businesses, voiced by AI. Your receptionist uses your business name, your services and your hours.</p>
          </div>
        </div>
      </div>
    </section>
  );
}
